var paths=new[]{"Assets/Scenes/PC_ShowRoom.unity","Assets/Scenes/TerrainTest.unity","Assets/Proto/Scenes/PC_Prototype.unity","Assets/Test/Cheon/Scenes/Test_CheonEnvironmentMap.unity"};var result=new System.Collections.Generic.List<object>();foreach(var path in paths){var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenPreviewScene(path);try{foreach(var root in scene.GetRootGameObjects())foreach(var tr in root.GetComponentsInChildren<Transform>(true)){if(tr.name.IndexOf("lantern",System.StringComparison.OrdinalIgnoreCase)<0&&tr.name.IndexOf("등")<0)continue;var renderers=tr.GetComponentsInChildren<Renderer>(true);var bounds=new Bounds(tr.position,Vector3.zero);foreach(var r in renderers)bounds.Encapsulate(r.bounds);result.Add(new {scene=path,name=tr.name,prefab=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(tr.gameObject),scale=tr.lossyScale.ToString(),bounds=bounds.size.ToString(),renderers=renderers.Length,light=tr.GetComponentsInChildren<Light>(true).Length});}}finally{UnityEditor.SceneManagement.EditorSceneManager.ClosePreviewScene(scene);}}return result;
